view_spec.script:
exports.Task = function (options) {
    TolokaHandlebarsTask.call(this, options);
    var boxes = this.getTask().input_values.initial_boxes;
    if (!Array.isArray(boxes)) {
        throw new Error("Вход initial_boxes должен содержать массив рамок и иметь hidden: false.");
    }
    var output = this.getSolution().output_values;
    if (!output.preannotation_initialized) {
        if (!Array.isArray(output.result) || output.result.length === 0) {
            this.setSolutionOutputValue("result", JSON.parse(JSON.stringify(boxes)));
        }
        this.setSolutionOutputValue("preannotation_initialized", true);
    }
};
exports.Task.prototype = Object.create(TolokaHandlebarsTask.prototype);
exports.Task.prototype.constructor = exports.Task;
exports.Task.prototype.onRender = function () {
    var task = this;
    this.getField("result").getEditor().on("shapes:update", function (shapes) {
        if (shapes.length === 0) {
            task.setSolutionOutputValue("result", []);
        }
    });
};

exports.Task.prototype.validate = function (solution) {
    solution = solution || this.getSolution();
    var base = TolokaHandlebarsTask.prototype.validate.call(this, solution);
    if (base) return base;
    var output = solution.output_values;
    var boxes = output.result || [];
    var message;
    if (output.status === "boxes" && !boxes.length) {
        message = "Выделите бабочку рамкой или измените результат просмотра.";
    } else if (output.status !== "boxes" && boxes.length) {
        message = "Удалите рамки или выберите «Бабочки выделены рамками».";
    }
    if (message) return {task_id: this.getTask().id, errors: {status: {code: "INVALID", message: message}}};
    return null;
};

exports.Task = function (options) {
    TolokaHandlebarsTask.call(this, options);
};
exports.Task.prototype = Object.create(TolokaHandlebarsTask.prototype);
exports.Task.prototype.constructor = exports.Task;
exports.Task.prototype.onRender = function () {
    var root = this.getDOMElement();
    var svg = root.querySelector(".boxes");
    svg.replaceChildren();
    this.getTask().input_values.boxes.forEach(function (box) {
        var rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
        rect.setAttribute("x", box[0] * 1000);
        rect.setAttribute("y", box[1] * 1000);
        rect.setAttribute("width", (box[2] - box[0]) * 1000);
        rect.setAttribute("height", (box[3] - box[1]) * 1000);
        svg.appendChild(rect);
    });
    root.querySelector(".zoom").oninput = function (event) {
        root.querySelector(".check-stage").style.width = event.target.value + "%";
    };
    root.querySelector(".toggle-boxes").onclick = function () {
        svg.style.visibility = svg.style.visibility === "hidden" ? "visible" : "hidden";
    };
};

exports.Task.prototype.validate = function (solution) {
    solution = solution || this.getSolution();
    var base = TolokaHandlebarsTask.prototype.validate.call(this, solution);
    if (base) return base;
    var output = solution.output_values;
    if (output.status === "reviewed") {
        var errors = {};
        ["complete", "no_extra", "accurate"].forEach(function (field) {
            if (!output[field]) errors[field] = {code: "REQUIRED", message: "Выберите ответ."};
        });
        if (Object.keys(errors).length) return {task_id: this.getTask().id, errors: errors};
    }
    return null;
};

view_spec.styles:
.check-tools { display: flex; gap: 24px; margin-bottom: 12px; }
.check-viewport { overflow: auto; max-height: 75vh; }
.check-stage { position: relative; width: 100%; }
.check-stage img { display: block; width: 100%; }
.check-stage svg { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; }
.check-stage rect { fill: none; stroke: #ffb000; stroke-width: 2; vector-effect: non-scaling-stroke; }
